/**
 * A hand-written control plane, for testing {@link App} without one.
 *
 * Written out by hand rather than generated by a mocking library, and the reason is that
 * this file is **the second place the server's promises are written down**. The first is
 * `@bit/contracts`, which says what the shapes are; this says what a plausible answer
 * looks like — a target summary with every field filled, a transcript that is `absent`
 * because nobody kept one, a refusal carrying the sentence the operator will read. A
 * generated double says nothing, and a reader who wants to know what `startRun` comes
 * back with would have to go and run one.
 *
 * **Every answer is a function, and it takes the arguments.** `onTarget` is handed the
 * id, so the default can echo it back instead of a test having to restate it; `onRuns`
 * can close over a flag and answer differently before and after a stop. That is enough
 * sequencing for everything here without a queue, a matcher or a `.mockReturnValueOnce`.
 *
 * **It holds the token too.** {@link ServerClient} puts `setToken` and `storedToken` on
 * the same seam as the calls, so this double keeps them in two plain fields and no test
 * needs a working `sessionStorage` to find out how a wrong password is classified.
 *
 * It is deliberately *not* a simulated server. Nothing in here checks a token against
 * what `setToken` was given, or refuses a duplicate folder because it already holds one.
 * Those are the server's rules, the server has its own tests for them, and a second
 * implementation of them here would be a thing to keep in sync that nobody runs.
 */
import {
  bareToolName,
  bitMcpServerName,
  claudeCodeToolName,
  openCodeToolName,
} from "@bit/contracts";
import type {
  AssetView,
  AttemptTranscript,
  FolderListing,
  GoalBriefingView,
  GoalView,
  IntentView,
  HarnessInstanceView,
  ImporterModelView,
  LiveCursor,
  LiveFrame,
  LiveItem,
  LiveOpened,
  GoalConversationView,
  GoalNarrationView,
  GoalTurnAccepted,
  GoalUploadsAccepted,
  PlanRoundStarted,
  PlanRoundView,
  RoundNarration,
  RunStarted,
  RunStopped,
  RunningAttempt,
  RunningRound,
  ScopeImportView,
  ScopeView,
  SessionOpened,
  SessionProbe,
  TargetCounts,
  TargetCreated,
  TargetSummary,
  TargetView,
} from "@bit/contracts";
import type { Call, LiveClosed, ServerClient } from "../src/lib/client";

/** What one of {@link ServerClient}'s calls answers with, exactly as declared. */
type Answer<K extends keyof ServerClient> = ServerClient[K] extends (
  ...args: never[]
) => Promise<infer A>
  ? A
  : never;

/* ── The three outcomes ──────────────────────────────────────────────────────── */

export const ok = <A>(value: A): Call<A, never> => ({ _tag: "Ok", value });

/**
 * A refusal: the server answered, and the answer was no.
 *
 * `E` is inferred from what is passed, which is why a test can hand one refusal to a
 * method whose real error channel is six members wide — {@link Call} holds its error
 * covariantly. What it cannot do is hand `SessionRefused` to `transcript`: the slot's
 * own type is the contract's union for that endpoint, so a double cannot invent a
 * refusal the server could never send.
 */
export const refused = <E>(error: E): Call<never, E> => ({
  _tag: "Refused",
  error,
});

/** No server answered at this address, with whatever the transport said. */
export const unreachable = (detail: string): Call<never, never> => ({
  _tag: "Unreachable",
  detail,
});

/* ── Shapes, with every field filled ─────────────────────────────────────────── */

/**
 * A fixed instant, so a test never depends on when it ran.
 *
 * `App.fromSummary` turns `lastActivityAt` into a relative string against `Date.now()`,
 * and a row built "a moment ago" reads `now` while the same row built against a wall
 * clock a test cannot control reads whatever the machine was doing.
 */
export const AT = 1_700_000_000_000;

/**
 * A target with nothing authored: no entries, no labels, and no block for the agent.
 *
 * The state every target has the moment migration `0022` runs, and the one A4's empty
 * screen describes — the hunt still records everything it finds, it just arrives labelled
 * "not covered". A test that wants a scope builds one.
 */
export const emptyScope = (over: Partial<ScopeView> = {}): ScopeView => ({
  entries: [],
  hostLabels: [],
  assetLabels: [],
  promptBlock: null,
  ...over,
});

