/**
 * One record item, defaulted to a recorded observation.
 *
 * `origin: "record"` and a real `sequence` by default, because that is the channel the
 * day's claims are about: ordered, deduplicable, resumable. A test that wants the other
 * channel asks for it, which keeps "this item has no position" a thing a test states
 * rather than a thing it gets by forgetting a field.
 */
export const liveItem = (over: Partial<LiveItem> = {}): LiveItem => ({
  _tag: "item",
  id: "record:evt-1",
  origin: "record",
  sequence: 1,
  kind: "observation.recorded",
  at: AT,
  attemptId: "attempt-1",
  roundId: null,
  goalId: null,
  headline: "Observation recorded",
  body: "the endpoint did not rate limit",
  tool: null,
  toolName: null,
  input: null,
  output: null,
  callId: null,
  outcome: "negative",
  ...over,
});

/** One activity item: no sequence, an id in the activity space. */
export const liveActivity = (over: Partial<LiveItem> = {}): LiveItem =>
  liveItem({
    id: "activity:1",
    origin: "activity",
    sequence: null,
    kind: "tool.call",
    headline: "bash",
    body: "",
    tool: "bash",
    // A harness's own tool is not namespaced, so the reduced name equals the raw one. A
    // tool of *ours* is namespaced and must be built with {@link livePlannerCall}, never
    // typed out.
    toolName: "bash",
    input: '{"command":"curl -s http://127.0.0.1:4000/"}',
    // A real call id by default, because the thing most worth getting wrong about a tool
    // call is which result answers it: a default of `null` would let a test assert pairing
    // without ever saying which call it meant.
    callId: "call-1",
    outcome: null,
    ...over,
  });

/**
 * One call to a tool **this application registered**, named the way a driver names it.
 *
 * **The reason this helper exists is a shipped bug.** The planner chat's merge rule is keyed
 * on `add_intent`, and against a real round it matched nothing: a planner's tools arrive over
 * MCP, so the name on the wire is `mcp__bit-<roundId>__add_intent` under Claude Code and
 * `bit-<roundId>.add_intent` under OpenCode. Two test suites fabricated the bare name in both
 * fields and therefore asserted the implementation against a tool-name space the server never
 * produces — so neither could have caught it.
 *
 * So nothing here is typed by hand. The wire name is built by `@bit/contracts`'
 * {@link claudeCodeToolName} / {@link openCodeToolName}, and the reduced name by
 * {@link bareToolName} — the very function `run/liveTranscript.ts` calls. A fixture built
 * from the same module as the reducer cannot drift from it, and a change to either naming
 * breaks the reducer and the fixture together instead of silently only the reducer.
 *
 * `driver` defaults to Claude Code because that is the form the reviewer read out of a live
 * round's DOM; `"opencode"` emits the form DECISIONS.md §24.2 Q1 recorded from OpenCode's own
 * refusal message.
 */
export const livePlannerCall = (
  bare: string,
  options: {
    readonly roundId: string;
    readonly driver?: "claude-code" | "opencode";
    readonly over?: Partial<LiveItem>;
  },
): LiveItem => {
  const server = bitMcpServerName(options.roundId);
  const wire =
    (options.driver ?? "claude-code") === "opencode"
      ? openCodeToolName(server, bare)
      : claudeCodeToolName(server, bare);
  return liveActivity({
    kind: "tool.call",
    attemptId: null,
    roundId: options.roundId,
    headline: wire,
    body: "",
    tool: wire,
    toolName: bareToolName(wire, server) ?? null,
    input: null,
    output: null,
    outcome: null,
    ...options.over,
  });
};

/**
 * One call to a **goal agent's** tool, named the way a driver names it.
 *
 * {@link livePlannerCall}'s sibling, and it exists because its absence hid the same bug a
 * second time: the merge rule was keyed on the planner's two tools and the goal agent's
 * were left out, so a steer and a goal ending rendered twice on the newest surface in the
 * app for two slices. No web test named `steer_planner`, `wake_planner` or `end_goal` at
 * all, which is why nothing could fail.
 *
 * The server name is `bit-<goalId>` — `plan/goalConversation.ts` registers the goal
 * endpoint under the **goal's** id, not a round's — and the ids on the item are the ones
 * this surface really carries: a goal id from the agent's own caller scope, and no round
 * id, because the goal agent's narration is published under the goal subject.
 */
export const liveGoalAgentCall = (
  bare: string,
  options: {
    readonly goalId: string;
    readonly driver?: "claude-code" | "opencode";
    readonly over?: Partial<LiveItem>;
  },
): LiveItem => {
  const server = bitMcpServerName(options.goalId);
  const wire =
    (options.driver ?? "claude-code") === "opencode"
      ? openCodeToolName(server, bare)
      : claudeCodeToolName(server, bare);
  return liveActivity({
    kind: "tool.call",
    attemptId: null,
    roundId: null,
    goalId: options.goalId,
    headline: wire,
    body: "",
    tool: wire,
    toolName: bareToolName(wire, server) ?? null,
    input: null,
    output: null,
    outcome: null,
    ...options.over,
  });
};

